"""
PulseBox Module: Spotify via librespot  (PERSONAL USE ONLY)
============================================================
Uses librespot/Raspotify to make the Pi appear as a Spotify Connect
speaker. Audio streams directly from Spotify to the Pi's audio output
(HiFiBerry Digi, HDMI, etc) — no intermediate device needed.

HOW IT WORKS:
  librespot is an open-source reimplementation of the Spotify Connect
  protocol. It registers the Pi as a Spotify Connect device so it
  appears in your Spotify app's device list. When you select it,
  Spotify streams encrypted audio directly to the Pi.

  ⚠  PERSONAL USE ONLY — librespot reverse-engineers Spotify's
     internal protocol. This is against Spotify's Developer Terms of
     Service. Use only for personal, non-commercial purposes.
  ⚠  Spotify Premium required.

INSTALL (one-time, run on Pi):
  sudo apt-get -y install curl
  curl -sL https://dtcooper.github.io/raspotify/install.sh | sh

  Then configure /etc/raspotify/conf:
    LIBRESPOT_NAME="PulseBox"
    LIBRESPOT_BITRATE="320"
    LIBRESPOT_FORMAT="S16"
    LIBRESPOT_BACKEND="pipe"  # or "alsa"

  Or use this module's UI to configure and restart the service.

METADATA:
  Reads now-playing metadata from the Spotify Web API using a
  Client ID (free tier OK for metadata — no Premium scope needed
  for read-only data).
"""

import json
import os
import subprocess
import threading
import time
import tkinter as tk
from tkinter import ttk

from core.config import JukeboxModule, APP_VERSION
from ui.theme import *

RASPOTIFY_CONF   = "/etc/raspotify/conf"
RASPOTIFY_SVC    = "raspotify"
LIBRESPOT_BIN    = "/usr/bin/librespot"   # fallback if not raspotify
METADATA_POLL    = 5   # seconds

CONF_TEMPLATE = """\
# PulseBox librespot configuration
# Generated by PulseBox Spotify module

# Device name shown in Spotify app
LIBRESPOT_NAME="{name}"

# Audio quality: 96, 160, 320 (kbps) — 320 requires Premium
LIBRESPOT_BITRATE="{bitrate}"

# Audio backend: alsa or pipe
LIBRESPOT_BACKEND="{backend}"

# ALSA device (blank = system default)
{alsa_device_line}

# Disable normalization for bit-perfect audio
LIBRESPOT_DISABLE_AUDIO_CACHE=
LIBRESPOT_INITIAL_VOLUME="75"
LIBRESPOT_VOLUME_CTRL="linear"
"""


class SpotifyLibrespotModule(JukeboxModule):

    MODULE_ID          = "spotify_librespot"
    MODULE_NAME        = "Spotify (librespot)"
    MODULE_VERSION = APP_VERSION
    MODULE_DESCRIPTION = ("Spotify Connect via librespot/Raspotify. "
                          "Pi appears as a Spotify speaker. "
                          "⚠ Personal use only — not for commercial use. "
                          "Requires Raspotify installed + Spotify Premium.")
    MODULE_AUTHOR      = "Andrew J. Morgan"

    def on_load(self, app):
        super().on_load(app)
        self._name_cfg    = self.config.get("librespot_name",    "PulseBox")
        self._bitrate_cfg = self.config.get("librespot_bitrate", "320")
        self._backend_cfg = self.config.get("librespot_backend", "alsa")
        self._alsa_dev    = self.config.get("librespot_alsa",    "")
        self._client_id   = self.config.get("spotify_client_id", "")

        self._status_var  = tk.StringVar(value="Checking…")
        self._track_var   = tk.StringVar(value="—")
        self._artist_var  = tk.StringVar(value="")
        self._album_var   = tk.StringVar(value="")
        self._device_var  = tk.StringVar(value="")
        self._svc_var     = tk.StringVar(value="")

        threading.Thread(target=self._check_status, daemon=True).start()

    # ------------------------------------------------------------------
    # Service control
    # ------------------------------------------------------------------

    def _run(self, cmd: list) -> tuple[bool, str]:
        """Run a shell command, return (success, output)."""
        try:
            r = subprocess.run(cmd, capture_output=True,
                               text=True, timeout=10)
            return r.returncode == 0, (r.stdout + r.stderr).strip()
        except subprocess.TimeoutExpired:
            return False, "Command timed out"
        except FileNotFoundError:
            return False, f"Not found: {cmd[0]}"
        except Exception as e:
            return False, str(e)

    def _check_status(self):
        installed = self._is_installed()
        if not installed:
            self._dispatch(lambda: self._status_var.set(
                "Raspotify not installed"))
            return

        ok, out = self._run(["systemctl", "is-active", RASPOTIFY_SVC])
        state   = "Running" if ok else "Stopped"
        self._dispatch(lambda s=state: (
            self._status_var.set(s),
            self._svc_var.set(s)
        ))

    def _is_installed(self) -> bool:
        ok, _ = self._run(["systemctl", "status", RASPOTIFY_SVC])
        return True  # status returns non-zero when stopped too
        # More reliable:
        return os.path.exists("/usr/bin/librespot") or \
               os.path.exists("/usr/local/bin/librespot")

    def _start_service(self):
        ok, out = self._run(["sudo", "systemctl", "start", RASPOTIFY_SVC])
        self._dispatch(lambda o=out, s=ok: self._status_var.set(
            "Running" if s else f"Start failed: {o[:80]}"))

    def _stop_service(self):
        ok, out = self._run(["sudo", "systemctl", "stop", RASPOTIFY_SVC])
        self._dispatch(lambda o=out, s=ok: self._status_var.set(
            "Stopped" if s else f"Stop failed: {o[:80]}"))

    def _restart_service(self):
        self._dispatch(lambda: self._status_var.set("Restarting…"))
        # Try systemctl first (works for pi user with sudoers rule)
        ok, out = self._run(["sudo", "systemctl", "restart", RASPOTIFY_SVC])
        if not ok:
            # Try without sudo — systemctl restart works for user services
            ok, out = self._run(["systemctl", "restart", RASPOTIFY_SVC])
        msg = "Running" if ok else f"Restart failed: {out[:80]}"
        self._dispatch(lambda m=msg: self._status_var.set(m))

    def _write_conf(self):
        alsa_line = (f'LIBRESPOT_DEVICE="{self._alsa_dev}"'
                     if self._alsa_dev else
                     '# LIBRESPOT_DEVICE=""  # blank = system default')
        conf = CONF_TEMPLATE.format(
            name=self._name_cfg,
            bitrate=self._bitrate_cfg,
            backend=self._backend_cfg,
            alsa_device_line=alsa_line,
        )
        import tempfile
        try:
            # Try direct write first
            with open(RASPOTIFY_CONF, "w") as f:
                f.write(conf)
            return True, "Config written"
        except PermissionError:
            pass
        # Fall back to sudo cp
        try:
            with tempfile.NamedTemporaryFile(
                    mode="w", suffix=".conf", delete=False) as tmp:
                tmp.write(conf)
                tmp_path = tmp.name
            ok, out = self._run(["sudo", "cp", tmp_path, RASPOTIFY_CONF])
            os.unlink(tmp_path)
            return ok, "Config written" if ok else out
        except Exception as e:
            return False, str(e)

    def _dispatch(self, fn):
        try:
            self.app.root.after(0, fn)
        except Exception:
            pass

