        tab2 = tk.Frame(nb, bg=BG_PANEL)
        nb.add(tab2, text="⚙  librespot Config")
        self._build_config_tab(tab2)

        tab3 = tk.Frame(nb, bg=BG_PANEL)
        nb.add(tab3, text="📋  Install Guide")
        self._build_install_tab(tab3)

        return nb

