    def _do_start(self):
        threading.Thread(target=self._start_service, daemon=True).start()

    def _do_stop(self):
        threading.Thread(target=self._stop_service, daemon=True).start()

    def _do_restart(self):
        threading.Thread(target=self._restart_service, daemon=True).start()

    def _do_check(self):
        threading.Thread(target=self._check_status, daemon=True).start()

    def _start_metadata(self):
        cid = self._cid_var.get().strip()
        if not cid:
            return
        self._client_id = cid
        self.config.set("spotify_client_id", cid)
        threading.Thread(target=self._metadata_loop,
                         daemon=True).start()

    def _metadata_loop(self):
        """Poll Spotify Web API for currently playing track (free tier)."""
        try:
            import spotipy
            from spotipy.oauth2 import SpotifyPKCE
            auth = SpotifyPKCE(
                client_id=self._client_id,
                redirect_uri="http://localhost:8765/callback",
                scope="user-read-currently-playing",
                cache_path=os.path.expanduser("~/.pulsebox_spotify_token"),
                open_browser=True,
            )
            sp = spotipy.Spotify(auth_manager=auth)
        except ImportError:
            self._dispatch(lambda: self._track_var.set(
                "spotipy not installed"))
            return

        while True:
            try:
                state = sp.current_playing()
                if state and state.get("item"):
                    item    = state["item"]
                    track   = item.get("name", "")
                    artists = ", ".join(
                        a["name"] for a in item.get("artists", []))
                    album   = item.get("album", {}).get("name", "")
                    self._dispatch(lambda t=track, ar=artists, al=album: (
                        self._track_var.set(t),
                        self._artist_var.set(ar),
                        self._album_var.set(al),
                    ))
                    # Album art
                    imgs = item.get("album", {}).get("images", [])
                    if imgs:
                        url = imgs[-1].get("url", "")
                        if url:
                            threading.Thread(
                                target=self._load_art,
                                args=(url,), daemon=True).start()
            except Exception as e:
                print(f"[Spotify metadata] {e}")
            time.sleep(METADATA_POLL)

    def _load_art(self, url):
        try:
            import requests, io
            from PIL import Image, ImageTk
            r   = requests.get(url, timeout=5)
            img = Image.open(io.BytesIO(r.content)).convert("RGBA")
            img = img.resize((64, 64), Image.Resampling.LANCZOS)
            ph  = ImageTk.PhotoImage(img)
            def _draw(p=ph):
                self._art_canvas.delete("all")
                self._art_canvas._photo = p
                self._art_canvas.create_image(32, 32,
                                              image=p, anchor="center")
            self._dispatch(_draw)
        except Exception:
            pass

